360	    /**
361	     * Builds the membership number for a new owner, formatted {@code '<customerCode>-M<YY>'} where YY is
362	     * the last two digits of the registration date's year (e.g. {@code 'NSW-1A2B3C4D-M26'}).
363	     *
364	     * @param customerCode     the owner's assigned customer code
365	     * @param registrationDate the owner's registration date
366	     * @return the assigned membership number
367	     */
368	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
369	        String yy = String.format("%02d", registrationDate.getYear() % 100);
370	        return String.format("%s-M%s", customerCode, yy);
371	    }
372	
373	    /**
374	     * Counts the existing owners that already share the given first name and last name, comparing
375	     * both case-insensitively. Called before a new owner is saved, so the returned value reflects
376	     * the number of namesakes that existed prior to this create.
377	     *
378	     * @param firstName the new owner's first name
379	     * @param lastName  the new owner's last name
380	     * @return the number of existing owners with the same first and last name
381	     */
382	    private int countNamesakes(String firstName, String lastName) {
383	        int count = 0;
384	        for (Owner existing : this.clinicService.findAllOwners()) {
385	            if (firstName.equalsIgnoreCase(existing.getFirstName())
386	                && lastName.equalsIgnoreCase(existing.getLastName())) {
387	                count++;
388	            }
389	        }
390	        return count;
391	    }
