393	    /**
394	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
395	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
396	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
397	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
398	     * string is what gets stored and returned.
399	     *
400	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
401	     *
402	     * <p>Once in E.164 form the national-number length is validated against the country code: a
403	     * {@code +61} (Australia) number must carry exactly 9 national digits and a {@code +1} (NANP)
404	     * number exactly 10 (see {@link #COUNTRY_NATIONAL_LENGTHS}). Country codes without a configured
405	     * rule are accepted on the general 8-to-15 digit length alone.
406	     *
407	     * @param telephone the raw telephone value supplied by the client
408	     * @return the normalized E.164 telephone number
409	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
410	     *                                 valid E.164 number (unexpected characters, not 8 to 15 digits
411	     *                                 after the {@code '+'}, or the wrong national-number length for
412	     *                                 its country code)
413	     */
414	    private static String normalizeTelephone(String telephone) {
415	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
416	        String digits;
417	        if (cleaned.startsWith("+")) {
418	            digits = cleaned.substring(1);
419	        } else {
420	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
421	            digits = "61" + national;
422	        }
423	        if (!digits.matches("[0-9]{8,15}")) {
424	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
425	                "telephone could not be normalized to a valid E.164 number");
426	        }
427	        validateNationalNumberLength(digits);
428	        return "+" + digits;
429	    }
430	
431	    /**
432	     * International dialling codes mapped to the exact number of national (subscriber) digits an
433	     * E.164 number for that country must carry: {@code +61} (Australia) requires 9 national digits
434	     * and {@code +1} (NANP) requires 10. Country codes absent from this map have no length rule.
435	     */
436	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTHS = Map.of("61", 9, "1", 10);
437	
438	    /**
439	     * Validates the national-number length of an E.164 number (its digits, without the leading
440	     * {@code '+'}) against its country code. The longest configured dialling code that prefixes the
441	     * number selects the rule; if none is configured the number passes (only the general 8-to-15
442	     * digit rule applies).
443	     *
444	     * @param digits the E.164 digits without the leading {@code '+'}
445	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the number of national
446	     *                                 digits does not match the country code's required length
447	     */
448	    private static void validateNationalNumberLength(String digits) {
449	        COUNTRY_NATIONAL_LENGTHS.keySet().stream()
450	            .filter(digits::startsWith)
451	            .max(Comparator.comparingInt(String::length))
452	            .ifPresent(code -> {
453	                int nationalLength = digits.length() - code.length();
454	                if (nationalLength != COUNTRY_NATIONAL_LENGTHS.get(code)) {
455	                    throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
456	                        "telephone must have " + COUNTRY_NATIONAL_LENGTHS.get(code)
457	                            + " national digits for country code +" + code);
458	                }
459	            });
460	    }
461	
462	    /**
463	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
464	     * containing at least one dot, none of the three sections containing whitespace or an
465	     * additional {@code @}.
466	     */
467	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
468	
469	    /**
470	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
471	     * (email is optional). When a value is supplied it must be a syntactically valid address; the
472	     * value is then stored and returned lower-cased.
473	     *
474	     * @param email the raw email value supplied by the client, possibly {@code null}
475	     * @return the lower-cased email, or {@code null} when none was supplied
476	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
477	     *                                 is not a syntactically valid address
478	     */
479	    private static String normalizeEmail(String email) {
480	        if (email == null) {
481	            return null;
482	        }
483	        if (!EMAIL_PATTERN.matcher(email).matches()) {
484	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
485	                "email must be a syntactically valid address");
486	        }
487	        return email.toLowerCase(Locale.ROOT);
488	    }
