490	    /**
491	     * Fixed region-to-inclusive-postcode-range table. The postcode of an owner whose city maps to a
492	     * known region (via {@link OwnerMapper#CITY_REGION}) must fall within its region's range: NSW
493	     * 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}} inclusive.
494	     */
495	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
496	        "NSW", new int[] {2000, 2099},
497	        "VIC", new int[] {3000, 3099},
498	        "QLD", new int[] {4000, 4099});
499	
500	    /**
501	     * Validates an owner's optional postcode against the city's region. Postcode is validated only
502	     * when present ({@code null} is accepted, keeping the request contract backward-compatible). The
503	     * four-digit format is enforced by request validation; here the value is range-checked: when the
504	     * city maps to a known region (via {@link OwnerMapper#CITY_REGION}) the postcode must fall within
505	     * that region's inclusive range (see {@link #REGION_POSTCODE_RANGES}). A city with no known region
506	     * accepts any four-digit postcode.
507	     *
508	     * @param city     the owner's city
509	     * @param postcode the owner's postcode, possibly {@code null}
510	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a supplied postcode is
511	     *                                 out of range for the city's region
512	     */
513	    private static void validatePostcode(String city, String postcode) {
514	        if (postcode == null) {
515	            return;
516	        }
517	        String region = OwnerMapper.CITY_REGION.get(city);
518	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
519	        if (range == null) {
520	            return;
521	        }
522	        int value = Integer.parseInt(postcode);
523	        if (value < range[0] || value > range[1]) {
524	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
525	                "postcode " + postcode + " is not valid for region " + region);
526	        }
527	    }
