529	    /**
530	     * Common street-type abbreviations expanded to their full word during address normalization.
531	     * Keys and values are upper-case; matching is done per whitespace-delimited token.
532	     */
533	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
534	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
535	
536	    /**
537	     * Normalizes an owner address for storage. Leading/trailing whitespace is trimmed and internal
538	     * runs of whitespace are collapsed to a single space, the value is upper-cased, and common
539	     * street-type abbreviations are expanded per token ({@code ST -> STREET}, {@code RD -> ROAD},
540	     * {@code AVE -> AVENUE}). This normalized value is what gets stored, returned, and used for every
541	     * address comparison (household duplicate detection and the shared household id).
542	     *
543	     * <p>For example {@code "  12  main  st "} is normalized to {@code "12 MAIN STREET"}.
544	     *
545	     * @param address the raw address supplied by the client, possibly {@code null}
546	     * @return the normalized address
547	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the address is blank
548	     *                                 after normalization (required field)
549	     */
550	    private static String normalizeAddress(String address) {
551	        String collapsed = address == null ? "" : address.trim().replaceAll("\\s+", " ");
552	        if (collapsed.isEmpty()) {
553	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
554	                "address must not be blank");
555	        }
556	        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
557	        StringBuilder normalized = new StringBuilder();
558	        for (int i = 0; i < tokens.length; i++) {
559	            if (i > 0) {
560	                normalized.append(' ');
561	            }
562	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
563	        }
564	        return normalized.toString();
565	    }
566	
567	    /**
568	     * Determines whether the given whole identity key already belongs to any owner other than the
569	     * one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g. on
570	     * create). The key is derived in one place — {@link OwnerMapper#toIdentityKey(Owner)}, the same
571	     * method that builds the {@code identityKey} returned on the DTO — so the value governing the
572	     * 409 is exactly the value clients see. Only an exact full-key match counts as a duplicate.
573	     *
574	     * @param identityKey the identity key to look for
575	     * @param excludeId   id of an owner to ignore during the check, or {@code null} for none
576	     * @return {@code true} if another owner already has the same identity key
577	     */
578	    private boolean isIdentityKeyInUse(String identityKey, Integer excludeId) {
579	        for (Owner existing : this.clinicService.findAllOwners()) {
580	            if (excludeId != null && excludeId.equals(existing.getId())) {
581	                continue;
582	            }
583	            if (identityKey.equals(ownerMapper.toIdentityKey(existing))) {
584	                return true;
585	            }
586	        }
587	        return false;
588	    }
589	
590	}
